+  const store = fresh();
+  const mk = (id, receivedOn, expires) =>
+    ({ id, itemId: 4, lot: `T-${id}`, qty: 1, receivedOn, expires, location: "dry" });
+  store.data.batches = store.data.batches.filter((b) => b.itemId !== 4);
+  store.data.batches.push(
+    mk(101, "2026-10-01", null),
+    mk(102, "2026-10-10", "2026-12-01"),
+    mk(103, "2026-10-05", "2026-12-01"),
+    mk(104, "2026-10-05", "2026-12-01"),
